input.command:
cat > eas.json <<'EOF'
{
  "cli": {
    "version": ">= 12.0.0",
    "appVersionSource": "remote"
  },
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal",
      "android": {
        "buildType": "apk"
      }
    },
    "production": {
      "autoIncrement": true,
      "android": {
        "buildType": "app-bundle"
      }
    }
  },
  "submit": {
    "production": {
      "ios": {
        "ascAppId": "REPLACE_WITH_APP_STORE_CONNECT_APP_ID"
      },
      "android": {
        "serviceAccountKeyPath": "./secrets/play-service-account.json",
        "track": "production",
        "releaseStatus": "draft"
      }
    }
  }
}
EOF
python3 - <<'EOF'
import json
d=json.load(open('app.json'))
del d['expo']['ios']['buildNumber']; del d['expo']['android']['versionCode']
json.dump(d,open('app.json','w'),indent=2); open('app.json','a').write('\n')
EOF
printf '\n# Google Play service account key (EAS Submit)\nsecrets/\n' >> .gitignore
git diff --stat

